/* C89 casts retain original matching objects and return null for mismatches/primitives. */
#include "flashvm/execution.h"
#include "flashvm/standard.h"
#include <assert.h>
int main(void){FVM_Config cfg;FVM_Runtime *rt;unsigned v;assert(fvm_config_init(&cfg)==FVM_OK && fvm_runtime_create(&cfg,&rt)==FVM_OK);for(v=0;v<=8;++v){FVM_Context *c;FVM_Object *object;FVM_Value input,klass,out;unsigned char swf[]={'F','W','S',8,16,0,0,0,8,0,0,12,1,0,0,0};if(v && v<4)continue;assert(fvm_context_create(rt,&c)==FVM_OK);if(v){swf[3]=(unsigned char)v;assert(fvm_load_memory(c,swf,sizeof(swf))==FVM_OK);}assert(fvm_standard_install(c)==FVM_OK && fvm_construct(c,"Object",0,0,&object)==FVM_OK && fvm_get_global(c,"Object",&klass)==FVM_OK);fvm_value_undefined(&input);input.type=FVM_VALUE_OBJECT;input.object=object;assert(fvm_exec_cast(c,&input,&klass,&out)==FVM_OK && out.type==FVM_VALUE_OBJECT && out.object==object);assert(fvm_get_global(c,"String",&klass)==FVM_OK && fvm_exec_cast(c,&input,&klass,&input)==FVM_OK && input.type==FVM_VALUE_NULL);fvm_value_number(&input,42);assert(fvm_get_global(c,"Number",&klass)==FVM_OK && fvm_exec_cast(c,&input,&klass,&klass)==FVM_OK && klass.type==FVM_VALUE_NULL);fvm_value_number(&out,99);assert(fvm_exec_cast(c,0,&klass,&out)==FVM_INVALID_ARGUMENT && out.number==99);if(v){fvm_value_number(&klass,17);assert(fvm_exec_cast(c,&input,&klass,&out)==FVM_OK && out.type==FVM_VALUE_NULL);}fvm_context_destroy(c);}fvm_runtime_destroy(rt);return 0;}
